104	PrinterSetupDialog::PrinterSetupDialog(wxWindow* parent, const ShellTheme& theme, bool dark,
105	                                       std::unique_ptr<PrinterSetupController> controller,
106	                                       std::vector<DiscoveredPrinter> discovered,
107	                                       bool agent_connected,
108	                                       MakeSetupWebViewFn make_setup_webview,
109	                                       ConnectFn connect,
110	                                       std::function<void()> on_agent_configured)
111	    : DPIDialog(parent, wxID_ANY, _L("Add a printer"), wxDefaultPosition, wxDefaultSize,
112	                wxBORDER_NONE),
113	      m_theme(theme), m_palette(theme.palette(dark)), m_controller(std::move(controller)),
114	      m_discovered(std::move(discovered)), m_agent_connected(agent_connected),
115	      m_make_setup_webview(std::move(make_setup_webview)), m_connect(std::move(connect)), m_timer(this),
116	      m_on_agent_configured(std::move(on_agent_configured))
117	{
118	    SetBackgroundColour(m_palette.surface_raised);
119	    SetName(_L("Add a printer"));
120	    m_root = new wxBoxSizer(wxVERTICAL);
121	    SetSizer(m_root);
122	    Bind(wxEVT_TIMER, &PrinterSetupDialog::on_timer, this);
123	    Bind(wxEVT_CLOSE_WINDOW, [this](wxCloseEvent&) { EndModal(wxID_CANCEL); });
124	    Bind(wxEVT_CHAR_HOOK, [this](wxKeyEvent& event) {
125	        if (event.GetKeyCode() == WXK_ESCAPE)
126	            EndModal(wxID_CANCEL);
127	        else
128	            event.Skip();
129	    });
130	    rebuild();
131	}
132	
