153	    result->SetName(text);
154	    result->SetToolTip(text);
155	    if (primary) style_primary_button(*result, m_theme, m_palette, m_theme.metrics().button.primary);
156	    else style_button(*result, m_theme, m_palette, m_theme.metrics().button.secondary);
157	    result->Bind(wxEVT_BUTTON, [invoke = std::move(invoke)](wxCommandEvent&) { invoke(); });
158	    return result;
