161	wxHyperlinkCtrl* PrinterSetupDialog::link(wxWindow* parent, const wxString& text,
162	                                          std::function<void()> invoke, bool accent)
163	{
164	    auto* result = new wxHyperlinkCtrl(parent, wxID_ANY, text, "action");
165	    result->SetName(text);
166	    wxFont font = m_theme.font(TextRole::BodySmallBold);
167	    font.SetUnderlined(accent);
168	    result->SetFont(font);
169	    const wxColour& colour = accent ? m_palette.action_primary : m_palette.text_primary;
